package com.bank.adapter;

import java.math.BigDecimal;
import java.util.logging.Logger;

interface PaymentProcessor {                     // the bank's clean target interface
    boolean pay(String accountId, BigDecimal rupees);
}

class RazorpayGateway {                           // incompatible third-party API
    String charge(String customerRef, long amountInPaise, String currency) {
        Logger.getLogger("RZP").info("Razorpay charged " + amountInPaise + " paise " + currency);
        return "SUCCESS";                         // vendor-specific response
    }
}

class RazorpayAdapter implements PaymentProcessor {   // adapter translates target → vendor
    private final RazorpayGateway gateway;
    RazorpayAdapter(RazorpayGateway gateway) { this.gateway = gateway; }
    public boolean pay(String accountId, BigDecimal rupees) {
        long paise = rupees.multiply(new BigDecimal("100")).longValueExact(); // rupees → paise
        String result = gateway.charge(accountId, paise, "INR");              // call vendor
        return "SUCCESS".equals(result);                                      // normalise response
    }
}

public class AdapterDemo {
    public static void main(String[] args) {
        Logger log = Logger.getLogger("PAY");
        PaymentProcessor processor = new RazorpayAdapter(new RazorpayGateway()); // bank uses its own interface
        boolean ok = processor.pay("SAV2001", new BigDecimal("5000"));  // Rajesh pays 5000 rupees
        log.info("Payment success? " + ok);
    }
}
